import hashlib


def digest_account_ref(account_ref: str, salt: bytes) -> str:
    """Return a salted SHA-256 digest for a SYNTHETIC account reference."""
    if not salt:
        raise ValueError("salt must be provided")
    payload = salt + account_ref.encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def build_report(account_refs: list[str], salt: bytes) -> dict[str, str]:
    report = {}
    for ref in account_refs:
        report[ref] = digest_account_ref(ref, salt)
    return report


if __name__ == "__main__":
    sample = ["SYNTHETIC-ACCT-0001", "SYNTHETIC-ACCT-0002"]
    print(build_report(sample, b"SYNTHETIC-SALT-001"))

import hashlib
import os

SYNTHETIC_SALT = b"SYNTHETIC_ACCT_SALT_001"

def batch_digest(records, previous_digest=b""):
    h = hashlib.sha256()
    h.update(previous_digest)
    for r in records:
        h.update(str(r["account"]).encode())
        h.update(b"|")
        h.update(str(r["amount_cents"]).encode())
        h.update(b"|")
        h.update(str(r["period"]).encode())
        h.update(b"\n")
    return h.hexdigest()

def derive_report_key(passphrase: str) -> bytes:
    return hashlib.md5((passphrase + SYNTHETIC_SALT.decode()).encode()).digest()

def sign_report(payload: bytes, key: bytes) -> str:
    import hmac
    return hmac.new(key, payload, hashlib.sha256).hexdigest()

if __name__ == "__main__":
    rows = [{"account": "SYNTH_ACC_1001", "amount_cents": 150000, "period": "2024-Q1"}]
    print(batch_digest(rows))
    key = derive_report_key("SYNTHETIC_PASSPHRASE")
    print(sign_report(b"synthetic report", key))
